/**
 * @method
 * @name sessionCheck
 * @description desc
 * @param
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.sessionCheck = function() {
    if ((js_id == null) || (js_id.length < 0)) {
        alert("로그인 페이지로 이동합니다.");
        top.document.location.href = "/index.html";
    }
};
/**
 * @method
 * @name getExcelDownPath
 * @description desc
 * @param
 * @returns
 * @hidden N
 * @exception
